/bin/bash -c "python3 - <<'PY'
from pathlib import Path
for i in [11,12,13,14,54,55,56,57,58,59,60]:
    t=Path(f'tmp/pdfs/page-{i:02}.txt').read_text()
    if i>=54:
        lines=t.splitlines()
        keep=[]
        for j,line in enumerate(lines):
            if line.startswith('Answer:') or line.startswith('Justification:'):
                for k in range(max(j-4,0),min(j+8,len(lines))):
                    if lines[k].startswith('Guidelines:'): break
                    keep.append((k,lines[k]))
        t='\\n'.join(line for k,line in sorted(dict(keep).items()))
    print(f'\\n--- PAGE {i} ---\\n'+t)
PY"
